const ids = ["G01","G02","G03","G04","G05","G06"];
const results = await Promise.all(ids.map(id => tools.origin_packet({case_id: id})));
const out = [];
for (const r of results) {
  const c = r.cases[0];
  const e = c.evidence;
  const src = new Map();
  for (const m of e.material_index) src.set(m.id, m.source_id);
  const parents = new Map();
  for (const l of e.links) {
    if (l.relation !== "derivation") continue;
    if (!parents.has(l.child)) parents.set(l.child, []);
    parents.get(l.child).push(l.parent);
  }
  // ensure every material id node exists
  for (const id of src.keys()) if (!parents.has(id)) parents.set(id, []);
  const memo = new Map();
  const visiting = new Set();
  const originsOf = (id) => {
    if (memo.has(id)) return memo.get(id);
    if (visiting.has(id)) throw new Error("cycle at " + id);
    visiting.add(id);
    const ps = parents.get(id) || [];
    let set;
    if (ps.length === 0) {
      set = new Set([src.get(id)]);
    } else {
      set = new Set();
      for (const p of ps) for (const o of originsOf(p)) set.add(o);
    }
    visiting.delete(id);
    memo.set(id, set);
    return set;
  };
  const all = new Set();
  const perNode = {};
  for (const id of src.keys()) {
    const s = originsOf(id);
    perNode[id] = [...s].sort();
    for (const o of s) all.add(o);
  }
  // compare with precomputed item origins
  const mismatches = [];
  for (const it of (e.items || [])) {
    const comp = perNode[it.id];
    const rec = (it.origins || []).slice().sort();
    if (JSON.stringify(comp) !== JSON.stringify(rec)) mismatches.push({id: it.id, comp, rec});
  }
  const queries = c.query_ids.map(q => ({material_id: q, origins: perNode[q] || null}));
  out.push({id: c.id, recorded_origin_count: e.recorded_origin_count, computedOriginCount: all.size, computedOrigins: [...all].sort(), queries, precomputedMismatches: mismatches});
}
console.log(JSON.stringify(out, null, 1));
